/// A text style token. Sizes are logical pixels at text scale 1.
class AkTextToken {
  const AkTextToken(this.family, this.size, this.lineHeight, this.weight);
  final String family;
  final double size;
  final double lineHeight;
  final FontWeight weight;
}

abstract final class AkTextTokens {
  static const display = 'Bricolage Grotesque';
  static const sans = 'Geist';

  /// `display-xl`
  static const displayXl = AkTextToken(display, 44, 46, FontWeight.w700);

  /// `figure-xl`
  static const figureXl = AkTextToken(display, 40, 44, FontWeight.w700);

  /// `display-lg`
  static const displayLg = AkTextToken(display, 30, 34, FontWeight.w700);

  /// `headline`
  static const headline = AkTextToken(display, 23, 28, FontWeight.w600);

  /// `title`
  static const title = AkTextToken(display, 18, 22, FontWeight.w600);

  /// `figure-lg`
  static const figureLg = AkTextToken(display, 34, 38, FontWeight.w700);

  /// `title-lg`
  static const titleLg = AkTextToken(display, 24, 28, FontWeight.w700);

  /// `display-sm`
  static const displaySm = AkTextToken(display, 22, 26, FontWeight.w700);

  /// `headline-sm`
  static const headlineSm = AkTextToken(display, 20, 24, FontWeight.w600);

  /// `keypad`
  static const keypad = AkTextToken(display, 28, 32, FontWeight.w600);

  /// `body`
  static const body = AkTextToken(sans, 14, 20, FontWeight.w400);

  /// `body-strong`
  static const bodyStrong = AkTextToken(sans, 14, 20, FontWeight.w600);

  /// `figure`
  static const figure = AkTextToken(sans, 14, 20, FontWeight.w600);

  /// `caption`
  static const caption = AkTextToken(sans, 12, 16, FontWeight.w500);

  /// `body-lg`
  static const bodyLg = AkTextToken(sans, 16, 24, FontWeight.w400);

  /// `button`
  static const button = AkTextToken(sans, 16, 20, FontWeight.w600);

  /// `body-md`
  static const bodyMd = AkTextToken(sans, 15, 20, FontWeight.w500);

  /// `body-sm`
  static const bodySm = AkTextToken(sans, 13, 18, FontWeight.w400);

  /// `caption-strong`
  static const captionStrong = AkTextToken(sans, 12, 16, FontWeight.w600);

  /// `chart-label`
  static const chartLabel = AkTextToken(sans, 11, 14, FontWeight.w400);
}

/// Spacing steps.
abstract final class AkSpace {
  /// `space-0h`: Between a stacked label and figure; between stacked bar segments. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double s0h = 2;

  /// `space-1`: Between a label and its value.
  static const double s1 = 4;

  /// `space-1h`: Between small chips; between a bar and its label. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double s1h = 6;

  /// `space-2`: Between chips, between an icon and its label.
  static const double s2 = 8;

  /// `space-2h`: Inside stat tiles; between list items in a group. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double s2h = 10;

  /// `space-3`: Between cards, between an icon tile and row text.
  static const double s3 = 12;

  /// `space-3h`: Gap between items on pushed screens. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double s3h = 14;

  /// `space-4`: Card padding.
  static const double s4 = 16;

  /// `space-5`: Between sections on Settings pages; bottom padding of pushed screens. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double s5 = 20;

  /// `space-6`: Screen side padding, between sections.
  static const double s6 = 24;
}

/// Corner radii at the "Rounded" setting. Read them through AkMetrics, which applies the Corners setting.
abstract final class AkRadiusTokens {
  /// `radius-xs`: Heat-calendar cells, legend swatches. Added 19 Nov 2026 from the drawn screens; needs a design check.
  static const double xs = 4;

  /// `radius-sm`: Progress and share bars.
  static const double sm = 5;

  /// `radius-md`: Icon tiles, stat tiles.
  static const double md = 10;

  /// `radius-lg`: Cards and full-width buttons.
  static const double lg = 14;

  /// `radius-pill`: Chips and compact buttons, 44px tall.
  static const double pill = 22;
}

/// Component sizes.
abstract final class AkSize {
  /// `size-target`: Smallest tappable height and width.
  static const double target = 44;

  /// `size-row`: A list or settings row.
  static const double row = 52;

  /// `size-input`: A text input.
  static const double input = 48;

  /// `size-button`: A full-width primary button.
  static const double button = 54;

  /// `size-nav`: Bottom navigation bar.
  static const double nav = 64;

  /// `size-add-disc`: The Add disc in the bottom navigation.
  static const double addDisc = 48;

  /// `size-tile`: Icon tile in a list row.
  static const double tile = 36;

  /// `size-tile-sm`: Icon tile in a compact row (Home share rows, forecast card).
  static const double tileSm = 32;

  /// `size-tile-lg`: Category identity tile.
  static const double tileLg = 48;

  /// `size-icon`: Icon inside a row tile.
  static const double icon = 20;

  /// `size-icon-nav`: Navigation icon.
  static const double iconNav = 22;

  /// `size-pinned-form-min`: Add keeps the kind and amount pinned at the top only while at least this much height is free above the keyboard; less, and the amount scrolls with the form.
  static const double pinnedFormMin = 520;

  /// `size-pin-key`: Largest PIN keypad key, reached on wide phones; narrow phones shrink keys to fit, never under the 44px target.
  static const double pinKey = 84;

  /// `size-icon-add`: The plus inside the Add disc on the bottom bar (the disc itself stays 48px).
  static const double iconAdd = 28;

  /// `size-icon-lg`: A lone icon heading an empty or not-yet card, as HomeEmpty.html draws the chart icon.
  static const double iconLg = 28;

  /// `size-switch-w`: Switch track width.
  static const double switchW = 48;

  /// `size-switch-h`: Switch track height.
  static const double switchH = 28;

  /// `size-bar`: Share bar thickness.
  static const double bar = 6;

  /// `size-bar-lg`: Budget and progress bar thickness.
  static const double barLg = 10;

  /// `size-icon-sm`: Icon in a compact tile, a segment, a chip or a link (Home, Add, Settings).
  static const double iconSm = 18;

  /// `size-icon-xs`: Icon inside the suggestion pill on Add.
  static const double iconXs = 14;

  /// `size-tile-md`: Category tile in the Add grid.
  static const double tileMd = 40;

  /// `size-cat-cell`: A category cell in the Add grid.
  static const double catCell = 72;

  /// `size-dot`: Account colour dot beside a name.
  static const double dot = 10;

  /// `size-pill`: Suggestion pill and small status chips.
  static const double pill = 28;

  /// `size-chart`: Height of the bars on Calendar (Day, Week, Quarter, Year).
  static const double chart = 160;

  /// `size-stroke`: A legend line or chart stroke. Added in phase 3 for the Insights legend; design check.
  static const double stroke = 2;
}
